begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','create_temporary_room',array['uuid','text','text','text','text','text','text'],'Temporary creation has an atomic service boundary');
select has_function('private','close_expired_temporary_rooms',array['timestamp with time zone'],'Temporary expiry has an authoritative time-controlled boundary');
update private.room_kind_features set enabled=false where room_kind='temporary';
select throws_ok($$select public.create_temporary_room('28600000-0000-4000-8000-000000000001','QA','Host','watch','TEMP286',repeat('a',64),repeat('b',64))$$,'42501',null,'creation is gated off by default');
update private.room_kind_features set enabled=true where room_kind='temporary';
select set_config('test.temp',public.create_temporary_room('28600000-0000-4000-8000-000000000001','QA','Host','watch','TEMP286',repeat('a',64),repeat('b',64))::text,true);
select is((select count(*)::int from public.room_settings where room_id='28600000-0000-4000-8000-000000000001'),1,'creation includes settings');
select is((select count(*)::int from public.room_members where room_id='28600000-0000-4000-8000-000000000001'),1,'creation includes guest host');
select set_config('test.member',current_setting('test.temp')::jsonb->'member'->>'id',true);
select throws_ok($$select public.create_temporary_room('28600000-0000-4000-8000-000000000002','', 'Host','listen','BAD286',repeat('c',64),repeat('d',64))$$,'22023',null,'invalid creation cannot partially insert');
select is((select count(*)::int from public.rooms where id='28600000-0000-4000-8000-000000000002'),0,'invalid creation leaves no room');
select throws_ok($$update public.rooms set is_saved=true where id='28600000-0000-4000-8000-000000000001'$$,'23514',null,'star cannot make Temporary persistent');
select is(public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.member')::uuid,null,repeat('z',64),true),false,'wrong guest token cannot touch');
update private.temporary_room_lifecycle set last_activity_at=now()-interval '59 minutes' where room_id='28600000-0000-4000-8000-000000000001';
select is(public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.member')::uuid,null,repeat('b',64),false),true,'guest can inspect recovery room within grace');
select ok((select last_activity_at<now()-interval '58 minutes' from private.temporary_room_lifecycle where room_id='28600000-0000-4000-8000-000000000001'),'dashboard inspection does not refresh deadline');
select is(public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.member')::uuid,null,repeat('b',64),true),true,'verified rejoin refreshes activity');
select ok((select last_activity_at>now()-interval '1 minute' from private.temporary_room_lifecycle where room_id='28600000-0000-4000-8000-000000000001'),'rejoin gets full new grace');
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,is_anonymous) values('28600000-0000-4000-8000-000000000099','temporary@qa.test','{"display_name":"Account"}','{}',false);
insert into public.room_members(room_id,user_id,display_name,role) values('28600000-0000-4000-8000-000000000001','28600000-0000-4000-8000-000000000099','Account','guest');
select set_config('test.accountmember',(select id::text from public.room_members where user_id='28600000-0000-4000-8000-000000000099'),true);
select is(public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.accountmember')::uuid,'28600000-0000-4000-8000-000000000099',null,true),true,'active account member can touch');
set local role service_role;
select lives_ok($$select public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.accountmember')::uuid,'28600000-0000-4000-8000-000000000099',null,true)$$,'real service role can validate active account membership');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','28600000-0000-4000-8000-000000000099',true);
select throws_ok($$select public.pending_temporary_room_cleanup()$$,'42501',null,'account cannot invoke privileged cleanup');
select throws_ok($$select public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.accountmember')::uuid,'28600000-0000-4000-8000-000000000099',null,true)$$,'42501',null,'account cannot forge verified touch');
select throws_ok($$select public.create_temporary_room(gen_random_uuid(),'Forged','Host','watch','FORGED286',repeat('e',64),repeat('f',64))$$,'42501',null,'account cannot bypass creation server');
reset role;
create function pg_temp.temp_event(ident text,kind text) returns jsonb language sql as $$
 select jsonb_build_array(jsonb_build_object('authority_event_id',ident,'idempotency_key',ident,'schema_version',1,'event_type',kind,
 'room_id','28600000-0000-4000-8000-000000000001','room_session_id','temp-session','playback_occurrence_id',ident,
 'actor_member_id',current_setting('test.accountmember'),'account_user_id','28600000-0000-4000-8000-000000000099',
 'source_type','youtube','media_id','temp286song','reason',case when kind='media_liked' then 'explicit_like' else 'add_as_next' end,
 'occurred_at',clock_timestamp(),'ingested_at',clock_timestamp())); $$;
select set_config('test.event',pg_temp.temp_event('temp286manual','queue_play_next')::text,true);
select public.ingest_recommendation_events(current_setting('test.event')::jsonb);
select public.ingest_recommendation_events(current_setting('test.event')::jsonb);
select is(public.read_room_learning_aggregates('28600000-0000-4000-8000-000000000001'),'[]'::jsonb,'replayed implicit choice never trains a room');
select is((select count(*)::int from private.recommendation_learning_eligibility l join public.recommendation_events e on e.id=l.event_id where e.authority_event_id='temp286manual' and (l.room_allowed or l.account_allowed)),0,'no account or room learning eligibility');
select public.ingest_recommendation_events(pg_temp.temp_event('temp286like','media_liked'));
insert into public.media_assets(id,owner_user_id,title,r2_bucket,r2_object_key,public_url,mime_type,file_size_bytes)
values('28600000-0000-4000-8000-000000000077','28600000-0000-4000-8000-000000000099','Catalogue fixture','qa-bucket','qa/temp286','https://example.test/fixture','video/webm',1);
select is((select preference_state from public.media_preferences where user_id='28600000-0000-4000-8000-000000000099' and media_id='temp286song'),'liked','explicit Like stays personal');
insert into public.queue_items(room_id,source_type,source_url,position,added_by_user_id) values('28600000-0000-4000-8000-000000000001','youtube','https://youtu.be/temp286song',0,'28600000-0000-4000-8000-000000000099');
insert into public.rooms(id,name,invite_code,invite_token_hash,room_kind,status,last_active_at,idle_deadline_at) values('28600000-0000-4000-8000-000000000088','Legacy','LEGACY286','legacy286','legacy','open',now()-interval '3 hours',now()-interval '2 hours');
select set_config('test.pendinglike',jsonb_set(pg_temp.temp_event('temp286pending','media_liked'),'{0,media_id}','"temp286pending"')::text,true);
update private.temporary_room_lifecycle set last_activity_at=now()-interval '1 hour' where room_id='28600000-0000-4000-8000-000000000001';
select is(private.close_expired_temporary_rooms(now()),1,'exact one-hour boundary closes Temporary');
set local role service_role;
select public.ingest_recommendation_events(current_setting('test.pendinglike')::jsonb);
reset role;
select is((select preference_state from public.media_preferences where user_id='28600000-0000-4000-8000-000000000099' and media_id='temp286pending'),'liked','captured Like still persists after room closure');
set local role service_role;
select is(public.is_temporary_room_open('28600000-0000-4000-8000-000000000001'),false,'media range authorization rejects expired room');
reset role;
select is((select status from public.rooms where id='28600000-0000-4000-8000-000000000088'),'open','Temporary expiry does not touch Legacy');
select is(private.close_expired_temporary_rooms(now()),0,'repeated expiry is idempotent');
select is(public.access_temporary_room('28600000-0000-4000-8000-000000000001',current_setting('test.member')::uuid,null,repeat('b',64),true),false,'late heartbeat cannot revive');
select throws_ok($$update public.rooms set status='open' where id='28600000-0000-4000-8000-000000000001'$$,'23514',null,'closed Temporary cannot reopen');
select is(public.finish_temporary_room_cleanup('28600000-0000-4000-8000-000000000001',true),false,'cannot purge before retention/live retirement');
select is(public.finish_temporary_room_cleanup('28600000-0000-4000-8000-000000000088',true),false,'cleanup acknowledgement cannot delete Legacy');
select is(public.finish_temporary_room_cleanup('28600000-0000-4000-8000-000000000001',false),true,'live retirement can be acknowledged');
select is(public.finish_temporary_room_cleanup('28600000-0000-4000-8000-000000000001',true),false,'24h retention still enforced after retirement');
update private.temporary_room_lifecycle set closed_at=now()-interval '24 hours' where room_id='28600000-0000-4000-8000-000000000001';
select ok(public.pending_temporary_room_cleanup() @> '[{"room_id":"28600000-0000-4000-8000-000000000001","purge":true}]'::jsonb,'purge becomes eligible at exact 24h boundary');
select is(public.finish_temporary_room_cleanup('28600000-0000-4000-8000-000000000001',true),true,'acknowledged eligible purge deletes room');
select is((select count(*)::int from public.room_members where room_id='28600000-0000-4000-8000-000000000001'),0,'membership cascades');
select is((select count(*)::int from public.queue_items where room_id='28600000-0000-4000-8000-000000000001'),0,'queue cascades');
select is((select count(*)::int from public.recommendation_events where room_id='28600000-0000-4000-8000-000000000001'),0,'operational recommendation events cascade');
select is((select preference_state from public.media_preferences where user_id='28600000-0000-4000-8000-000000000099' and media_id='temp286song'),'liked','explicit account Like survives purge');
select is((select preference_state from public.media_preferences where user_id='28600000-0000-4000-8000-000000000099' and media_id='temp286pending'),'liked','delayed explicit Like survives subsequent purge');
select is((select count(*)::int from public.media_assets where id='28600000-0000-4000-8000-000000000077'),1,'catalogue asset survives room purge');
select is(public.finish_temporary_room_cleanup('28600000-0000-4000-8000-000000000001',true),false,'repeat purge is harmless');
select public.ingest_recommendation_events(current_setting('test.event')::jsonb);
select is((select count(*)::int from public.recommendation_events where room_id='28600000-0000-4000-8000-000000000001'),0,'delayed replay cannot recreate purged room history');
set local role service_role;
select is(public.has_temporary_room_ended('28600000-0000-4000-8000-000000000001'),true,'purged link retains a UUID-only expiry receipt');
select is(public.has_temporary_room_ended('28600000-0000-4000-8000-000000000088'),false,'Legacy is never described as Temporary expiry');
reset role;
set local role authenticated;
select throws_ok($$select public.has_temporary_room_ended('28600000-0000-4000-8000-000000000001')$$,'42501',null,'expiry receipts are server-only');
reset role;
insert into auth.users(id,is_anonymous,raw_user_meta_data) values('28600000-0000-4000-8000-000000000098',false,'{"display_name":"Deleting owner"}');
select public.create_temporary_room('28600000-0000-4000-8000-000000000097','Owner deletion','Owner','watch','DELETE286',repeat('c',64),repeat('d',64));
update public.rooms set owner_user_id='28600000-0000-4000-8000-000000000098' where id='28600000-0000-4000-8000-000000000097';
delete from auth.users where id='28600000-0000-4000-8000-000000000098';
select is((select status from public.rooms where id='28600000-0000-4000-8000-000000000097'),'closed','account deletion closes owned Temporary room');
select is((select live_retired from private.temporary_room_lifecycle where room_id='28600000-0000-4000-8000-000000000097'),false,'account deletion retains retryable live cleanup');
select is(public.has_temporary_room_ended('28600000-0000-4000-8000-000000000097'),true,'deleted owner leaves an expiry explanation');
select * from finish();
rollback;
